display.text:
//! IUDS Core — Ders 1: API sözleşmesi.
//! Koştur: `cargo run` → http://127.0.0.1:3901/api/health
//! Test: `cargo test`

use axum::{
    Json, Router,
    http::StatusCode,
    routing::{get, post},
};
use serde::{Deserialize, Serialize};

// ---- Modeller (docs/10-mobil-app.md'deki sözleşme) ----

#[derive(Serialize)]
struct Health {
    ok: bool,
    service: &'static str,
}

#[derive(Serialize)]
struct Visit {
    id: String,
    person: String,
    trust: String, // L0/L1/L2
    score: f32,
    time: String,
}

#[derive(Deserialize)]
struct DoorCmd {
    visit_id: String,
    token: String, // Faz 1'de mock: boş olmamalı. Faz 4'te HMAC olacak.
}

#[derive(Serialize)]
struct DoorResp {
    ok: bool,
    action: &'static str,
    visit_id: String,
}

#[derive(Deserialize)]
struct TagCmd {
    name: String,
    host: Option<String>,
}

async fn health() -> Json<Health> {
    Json(Health { ok: true, service: "iuds-core" })
}

// Mock: gerçekte SQLite'dan gelecek. Şimdilik sabit 2 kayıt.
async fn visits_today() -> Json<Vec<Visit>> {
    Json(vec![
        Visit { id: "v-001".into(), person: "Ziyaretçi-2026-09-11-001".into(), trust: "L0".into(), score: 0.41, time: "18:40".into() },
        Visit { id: "v-002".into(), person: "Anne".into(), trust: "L2".into(), score: 0.93, time: "18:42".into() },
    ])
}

async fn door_open(Json(cmd): Json<DoorCmd>) -> Result<Json<DoorResp>, StatusCode> {
    if cmd.token.is_empty() || cmd.visit_id.is_empty() {
        return Err(StatusCode::BAD_REQUEST); // imzasız komut reddedilir
    }
    Ok(Json(DoorResp { ok: true, action: "open", visit_id: cmd.visit_id }))
}

async fn door_deny(Json(cmd): Json<DoorCmd>) -> Result<Json<DoorResp>, StatusCode> {
    if cmd.token.is_empty() || cmd.visit_id.is_empty() {
        return Err(StatusCode::BAD_REQUEST);
    }
    Ok(Json(DoorResp { ok: true, action: "deny", visit_id: cmd.visit_id }))
}

async fn tag_person(axum::extract::Path(id): axum::extract::Path<String>, Json(cmd): Json<TagCmd>) -> Json<serde_json::Value> {
    Json(serde_json::json!({ "ok": true, "id": id, "name": cmd.name, "host": cmd.host }))
}

fn app() -> Router {
    Router::new()
        .route("/api/health", get(health))
        .route("/api/visits/today", get(visits_today))
        .route("/api/door/open", post(door_open))
        .route("/api/door/deny", post(door_deny))
        .route("/api/persons/{id}/tag", post(tag_person))
}

#[tokio::main]
async fn main() {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:3901").await.unwrap();
    println!("iuds-core → http://127.0.0.1:3901/api/health");
    axum::serve(listener, app()).await.unwrap();
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn health_ok() {
        let h = health().await;
        assert!(h.0.ok);
    }

    #[tokio::test]
    async fn visits_mock_2_kayit() {
        let v = visits_today().await;
        assert_eq!(v.0.len(), 2);
    }

    #[tokio::test]
    async fn kapi_bos_token_red() {
        let r = door_open(Json(DoorCmd { visit_id: "v-1".into(), token: "".into() })).await;
        assert!(r.is_err());
    }
}

