//! IUDS karar motoru — `iuds-vision/decision.py` ile birebir aynı kural.
//! docs/02-guvenlik.md'deki AND kuralının sayısal hali:
//! KARAR = yüz eşleşti VE beden orada VE canlı VE track tutarlı.
//! Şüphede fail-closed: biri bile tutmazsa reddet.

pub const ESIK_YUZ: f32 = 0.65;
pub const ESIK_PRESENCE: f32 = 0.50;
pub const ESIK_LIVENESS: f32 = 0.60;
pub const MIN_TRACK_SURESI: f32 = 3.0;

/// Python tarafındaki `olay` dict'inin Rust karşılığı.
/// Skorlar 0-1 arası beklenir; aralığı `validate` kontrol eder.
#[derive(Debug, Clone)]
pub struct VisionScores {
    pub yuz: f32,
    pub presence: f32,
    pub liveness: f32,
    pub track_suresi: f32,
    pub whitelist: bool,
    pub birlikte_mi: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Decision {
    /// Aile: tüm katmanlar geçti.
    OtoAc,
    /// Ailenin misafiri: sorgulama yok, bilgi bildirimi.
    EslikliAc,
    /// Tanıdık değil: ev halkına sor.
    Sor,
    /// Spoof / eksik katman: kapı kapalı.
    Reddet,
}

impl Decision {
    /// DB + API'de saklanan kanonik ad (`docs/06` karar kümesi).
    pub fn as_str(self) -> &'static str {
        match self {
            Decision::OtoAc => "oto_ac",
            Decision::EslikliAc => "eslikli_ac",
            Decision::Sor => "soruldu",
            Decision::Reddet => "red",
        }
    }
}

/// Skor aralığını kontrol et. Hatalı skorla karar verilmez (fail-closed).
pub fn validate(s: &VisionScores) -> Result<(), &'static str> {
    for v in [s.yuz, s.presence, s.liveness] {
        if !(0.0..=1.0).contains(&v) || !v.is_finite() {
            return Err("skor 0-1 aralığında olmalı");
        }
    }
    if !s.track_suresi.is_finite() || s.track_suresi < 0.0 {
        return Err("track_suresi negatif olamaz");
    }
    Ok(())
}

pub fn decide(s: &VisionScores) -> (Decision, &'static str) {
    // 1) AND kuralı: biri bile tutmazsa red.
    if s.presence < ESIK_PRESENCE {
        return (Decision::Reddet, "beden yok (fotograf olabilir)");
    }
    if s.liveness < ESIK_LIVENESS {
        return (Decision::Reddet, "canlilik yok");
    }
    if s.track_suresi < MIN_TRACK_SURESI {
        return (Decision::Reddet, "takip cok kisa");
    }
    if s.yuz < ESIK_YUZ {
        // Eşlikli giriş istisnası: decision.py ile aynı — yüz tutmasa bile
        // aileyle yan yana gelen misafir sorgulanmadan alınır, loglanır.
        if s.birlikte_mi {
            return (Decision::EslikliAc, "ailenin misafiri, sorgulama yok");
        }
        return (Decision::Sor, "yuz tutmadi, ev halkina sor");
    }

    // 2) Buraya gelen: yüz + presence + liveness + track HEPSİ geçti.
    if s.birlikte_mi && !s.whitelist {
        return (Decision::EslikliAc, "ailenin misafiri, sorgulama yok");
    }
    if s.whitelist {
        return (Decision::OtoAc, "aile, tum katmanlar gecti");
    }
    (Decision::Sor, "tanidik degil, onay gerek")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn olay(yuz: f32, presence: f32, liveness: f32, sure: f32, wl: bool, birlikte: bool) -> VisionScores {
        VisionScores { yuz, presence, liveness, track_suresi: sure, whitelist: wl, birlikte_mi: birlikte }
    }

    #[test]
    fn anne_oto_ac() {
        let (k, _) = decide(&olay(0.93, 0.9, 0.85, 4.2, true, false));
        assert_eq!(k, Decision::OtoAc);
    }

    #[test]
    fn anne_misafir_eslikli() {
        // decision.py SENARYOLAR ile aynı: yüz düşük ama birlikte_mi=true.
        let (k, _) = decide(&olay(0.40, 0.9, 0.8, 5.0, false, true));
        assert_eq!(k, Decision::EslikliAc);
    }

    #[test]
    fn elde_fotograf_red() {
        let (k, _) = decide(&olay(0.91, 0.2, 0.1, 4.0, false, false));
        assert_eq!(k, Decision::Reddet);
    }

    #[test]
    fn tek_kare_red() {
        let (k, _) = decide(&olay(0.99, 0.9, 0.8, 0.4, false, false));
        assert_eq!(k, Decision::Reddet);
    }

    #[test]
    fn yabanci_sor() {
        let (k, _) = decide(&olay(0.41, 0.85, 0.75, 4.5, false, false));
        assert_eq!(k, Decision::Sor);
    }

    #[test]
    fn bozuk_skor_reddedilir() {
        let s = olay(9.9, 0.9, 0.8, 4.0, true, false);
        assert!(validate(&s).is_err());
    }
}

//! IUDS SQLite katmanı — tek yazar Rust.
//! Şema: docs/06-kayit-semasi.md + notes/01-Veritabani.md
//!
//! - persons: kim bu? (whitelist SADECE insan onayıyla)
//! - visits: ne zaman, ne oldu? (silme yok)
//! - command_log: kapı komutları, append-only (UPDATE/DELETE yok)

use chrono::Local;
use rusqlite::{Connection, Result, params};

pub const SCHEMA: &str = r#"
CREATE TABLE IF NOT EXISTS persons (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    tip         TEXT NOT NULL DEFAULT 'bilinmeyen',
    whitelist   INTEGER NOT NULL DEFAULT 0,
    host        TEXT,
    visit_count INTEGER NOT NULL DEFAULT 0,
    first_seen  TEXT NOT NULL,
    last_seen   TEXT NOT NULL,
    note        TEXT
);
CREATE TABLE IF NOT EXISTS visits (
    id        TEXT PRIMARY KEY,
    person_id TEXT NOT NULL REFERENCES persons(id),
    time      TEXT NOT NULL,
    camera    TEXT NOT NULL DEFAULT 'cam0',
    karar     TEXT NOT NULL,
    yuz       REAL NOT NULL,
    presence  REAL NOT NULL,
    liveness  REAL NOT NULL,
    group_id  TEXT,
    approved_by TEXT
);
CREATE INDEX IF NOT EXISTS idx_visits_time ON visits(time);
CREATE INDEX IF NOT EXISTS idx_visits_person ON visits(person_id);
CREATE TABLE IF NOT EXISTS command_log (
    id      INTEGER PRIMARY KEY AUTOINCREMENT,
    time    TEXT NOT NULL,
    action  TEXT NOT NULL,
    visit_id TEXT NOT NULL,
    ok      INTEGER NOT NULL,
    detail  TEXT
);
"#;

pub fn open(path: &str) -> Result<Connection> {
    let conn = Connection::open(path)?;
    conn.execute_batch(SCHEMA)?;
    Ok(conn)
}

pub fn open_memory() -> Result<Connection> {
    let conn = Connection::open_in_memory()?;
    conn.execute_batch(SCHEMA)?;
    Ok(conn)
}

pub fn now_str() -> String {
    Local::now().format("%Y-%m-%d %H:%M:%S").to_string()
}

pub fn today_prefix() -> String {
    Local::now().format("%Y-%m-%d").to_string()
}

/// Bilinmeyen kişi id'si: `Ziyaretçi-YYYY-AA-GG-NNN` (notes/01).
pub fn next_unknown_id(conn: &Connection) -> Result<String> {
    let day = Local::now().format("%Y-%m-%d").to_string();
    let day_compact = Local::now().format("%Y-%m-%d").to_string();
    let n: i64 = conn.query_row(
        "SELECT COUNT(*) FROM persons WHERE id LIKE ?1",
        params![format!("Ziyaretçi-{day_compact}-%")],
        |r| r.get(0),
    )?;
    let _ = day;
    Ok(format!("Ziyaretçi-{}-{:03}", day_compact, n + 1))
}

pub fn ensure_person(conn: &Connection, id: &str, name: &str) -> Result<()> {
    let t = now_str();
    conn.execute(
        "INSERT OR IGNORE INTO persons (id, name, tip, whitelist, visit_count, first_seen, last_seen)
         VALUES (?1, ?2, 'bilinmeyen', 0, 0, ?3, ?3)",
        params![id, name, t],
    )?;
    Ok(())
}

pub fn bump_visit_counter(conn: &Connection, person_id: &str) -> Result<()> {
    let t = now_str();
    conn.execute(
        "UPDATE persons SET visit_count = visit_count + 1, last_seen = ?1 WHERE id = ?2",
        params![t, person_id],
    )?;
    Ok(())
}

#[allow(clippy::too_many_arguments)]
pub fn insert_visit(
    conn: &Connection,
    visit_id: &str,
    person_id: &str,
    camera: &str,
    karar: &str,
    yuz: f32,
    presence: f32,
    liveness: f32,
    group_id: Option<&str>,
) -> Result<()> {
    conn.execute(
        "INSERT INTO visits (id, person_id, time, camera, karar, yuz, presence, liveness, group_id)
         VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9)",
        params![visit_id, person_id, now_str(), camera, karar, yuz, presence, liveness, group_id],
    )?;
    bump_visit_counter(conn, person_id)?;
    Ok(())
}

/// Append-only: komut loguna yaz, asla güncelleme/silme yapma.
pub fn log_command(conn: &Connection, action: &str, visit_id: &str, ok: bool, detail: &str) -> Result<()> {
    conn.execute(
        "INSERT INTO command_log (time, action, visit_id, ok, detail) VALUES (?1, ?2, ?3, ?4, ?5)",
        params![now_str(), action, visit_id, ok as i32, detail],
    )?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn unknown_id_artar() -> Result<()> {
        let conn = open_memory()?;
        let a = next_unknown_id(&conn)?;
        ensure_person(&conn, &a, &a)?;
        let b = next_unknown_id(&conn)?;
        assert_ne!(a, b);
        assert!(a.starts_with("Ziyaretçi-"));
        Ok(())
    }

    #[test]
    fn visit_ekle_sayaci_artirir() -> Result<()> {
        let conn = open_memory()?;
        ensure_person(&conn, "p1", "Anne")?;
        insert_visit(&conn, "v-1", "p1", "cam0", "oto_ac", 0.9, 0.9, 0.9, None)?;
        let n: i64 = conn.query_row("SELECT visit_count FROM persons WHERE id='p1'", [], |r| r.get(0))?;
        assert_eq!(n, 1);
        Ok(())
    }

    #[test]
    fn command_log_append_only() -> Result<()> {
        let conn = open_memory()?;
        log_command(&conn, "open", "v-1", true, "test")?;
        let n: i64 = conn.query_row("SELECT COUNT(*) FROM command_log", [], |r| r.get(0))?;
        assert_eq!(n, 1);
        Ok(())
    }
}

//! IUDS Core — Ders 4: SQLite + karar motoru + vision ingest.
//! Koştur: `cargo run` → http://127.0.0.1:3901/api/health
//! Test: `cargo test`
//!
//! Sözleşme: notes/03-Api-Sozlesmesi.md (değişirse panel + not aynı anda güncellenir).
//! Kural: decision.rs (docs/02). Tek yazar: bu servis (db.rs).

mod db;
mod decision;

use std::sync::Arc;

use axum::{
    Json, Router,
    extract::{Path, State},
    http::StatusCode,
    routing::{get, post},
};
use chrono::Local;
use decision::{Decision, VisionScores, decide, validate};
use serde::{Deserialize, Serialize};

// ---- Modeller ----

#[derive(Clone)]
struct AppState {
    db: Arc<tokio::sync::Mutex<rusqlite::Connection>>,
}

#[derive(Serialize)]
struct Health {
    ok: bool,
    service: &'static str,
}

#[derive(Serialize)]
struct Visit {
    id: String,
    person: String,
    trust: String, // L0/L1/L2
    score: f32,
    time: String,
}

/// Python vision'dan gelen olay. Skorlar YOLO + InsightFace + LD2410'dan
/// gelecek; şimdilik panel/test manuel basar.
#[derive(Deserialize)]
struct VisionEventReq {
    person_id: Option<String>,
    camera: Option<String>,
    yuz: f32,
    presence: f32,
    liveness: f32,
    track_suresi: f32,
    whitelist: Option<bool>,
    birlikte_mi: Option<bool>,
    group_id: Option<String>,
}

#[derive(Serialize)]
struct VisionEventResp {
    ok: bool,
    visit_id: String,
    person_id: String,
    karar: &'static str,
    neden: &'static str,
}

#[derive(Deserialize)]
struct DoorCmd {
    visit_id: String,
    token: String, // Faz 1'de mock: boş olmamalı. Faz 4'te HMAC olacak.
}

#[derive(Serialize)]
struct DoorResp {
    ok: bool,
    action: &'static str,
    visit_id: String,
}

#[derive(Deserialize)]
struct TagCmd {
    name: String,
    host: Option<String>,
    tip: Option<String>,
    /// whitelist SADECE insan onayıyla değişir; None = dokunma.
    whitelist: Option<bool>,
}

// ---- Handlers ----

async fn health() -> Json<Health> {
    Json(Health { ok: true, service: "iuds-core" })
}

fn trust_of(whitelist: i64, visit_count: i64) -> &'static str {
    if whitelist == 1 {
        "L2"
    } else if visit_count >= 3 {
        "L1"
    } else {
        "L0"
    }
}

async fn visits_today(State(st): State<AppState>) -> Result<Json<Vec<Visit>>, StatusCode> {
    let guard = st.db.lock().await;
    let prefix = db::today_prefix();
    let mut stmt = guard
        .prepare(
            "SELECT v.id, v.person_id, v.time, v.yuz, COALESCE(p.whitelist,0), COALESCE(p.visit_count,0)
             FROM visits v LEFT JOIN persons p ON p.id = v.person_id
             WHERE v.time LIKE ?1 ORDER BY v.time DESC LIMIT 100",
        )
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let rows = stmt
        .query_map([format!("{prefix}%")], |r| {
            Ok((
                r.get::<_, String>(0)?,
                r.get::<_, String>(1)?,
                r.get::<_, String>(2)?,
                r.get::<_, f32>(3)?,
                r.get::<_, i64>(4)?,
                r.get::<_, i64>(5)?,
            ))
        })
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let mut out = Vec::new();
    for r in rows {
        let (id, person, time, yuz, wl, cnt) = r.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
        // Panel sadece saati gösterir (18:42); DB'de tam tarih var.
        let short = time.get(11..16).unwrap_or(&time).to_string();
        out.push(Visit { id, person, trust: trust_of(wl, cnt).into(), score: yuz, time: short });
    }
    Ok(Json(out))
}

async fn vision_event(
    State(st): State<AppState>,
    Json(req): Json<VisionEventReq>,
) -> Result<Json<VisionEventResp>, StatusCode> {
    let scores = VisionScores {
        yuz: req.yuz,
        presence: req.presence,
        liveness: req.liveness,
        track_suresi: req.track_suresi,
        whitelist: req.whitelist.unwrap_or(false),
        birlikte_mi: req.birlikte_mi.unwrap_or(false),
    };
    validate(&scores).map_err(|_| StatusCode::BAD_REQUEST)?;
    let (karar, neden) = decide(&scores);
    let karar_str = karar.as_str();

    let guard = st.db.lock().await;
    // Kişi: verildiyse kullan, yoksa bilinmeyen id üret.
    let person_id = match req.person_id {
        Some(p) if !p.trim().is_empty() => p.trim().to_string(),
        _ => db::next_unknown_id(&guard).map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?,
    };
    db::ensure_person(&guard, &person_id, &person_id)
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    // Visit id: gün içi sayaç (v-YYYY-AA-GG-NNN).
    let day = Local::now().format("%Y-%m-%d").to_string();
    let n: i64 = guard
        .query_row("SELECT COUNT(*) FROM visits WHERE time LIKE ?1", [format!("{day}%")], |r| {
            r.get(0)
        })
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let visit_id = format!("v-{day}-{:03}", n + 1);
    let camera = req.camera.as_deref().unwrap_or("cam0");

    db::insert_visit(
        &guard,
        &visit_id,
        &person_id,
        camera,
        karar_str,
        scores.yuz,
        scores.presence,
        scores.liveness,
        req.group_id.as_deref(),
    )
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    // Kapı kararı da bir komut sayılır: oto/eslikli açılışları logla.
    if matches!(karar, Decision::OtoAc | Decision::EslikliAc) {
        let _ = db::log_command(&guard, karar_str, &visit_id, true, neden);
    }
    Ok(Json(VisionEventResp { ok: true, visit_id, person_id, karar: karar_str, neden }))
}

async fn door_open(
    State(st): State<AppState>,
    Json(cmd): Json<DoorCmd>,
) -> Result<Json<DoorResp>, StatusCode> {
    if cmd.token.is_empty() || cmd.visit_id.is_empty() {
        return Err(StatusCode::BAD_REQUEST); // imzasız komut reddedilir
    }
    let guard = st.db.lock().await;
    let _ = db::log_command(&guard, "open", &cmd.visit_id, true, "manuel acma");
    Ok(Json(DoorResp { ok: true, action: "open", visit_id: cmd.visit_id }))
}

async fn door_deny(
    State(st): State<AppState>,
    Json(cmd): Json<DoorCmd>,
) -> Result<Json<DoorResp>, StatusCode> {
    if cmd.token.is_empty() || cmd.visit_id.is_empty() {
        return Err(StatusCode::BAD_REQUEST);
    }
    let guard = st.db.lock().await;
    let _ = db::log_command(&guard, "deny", &cmd.visit_id, true, "manuel red");
    Ok(Json(DoorResp { ok: true, action: "deny", visit_id: cmd.visit_id }))
}

async fn tag_person(
    State(st): State<AppState>,
    Path(id): Path<String>,
    Json(cmd): Json<TagCmd>,
) -> Result<Json<serde_json::Value>, StatusCode> {
    if cmd.name.trim().is_empty() {
        return Err(StatusCode::BAD_REQUEST);
    }
    if let Some(t) = &cmd.tip {
        if !["aile", "misafir", "bilinmeyen", "kara-liste"].contains(&t.as_str()) {
            return Err(StatusCode::BAD_REQUEST);
        }
    }
    let guard = st.db.lock().await;
    db::ensure_person(&guard, &id, &cmd.name).map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    guard
        .execute(
            "UPDATE persons SET name = ?1, host = COALESCE(?2, host) WHERE id = ?3",
            rusqlite::params![cmd.name, cmd.host, id],
        )
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    if let Some(t) = cmd.tip {
        guard
            .execute("UPDATE persons SET tip = ?1 WHERE id = ?2", rusqlite::params![t, id])
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    }
    if let Some(wl) = cmd.whitelist {
        // İnsan onayı izi: komut loguna da düşer.
        guard
            .execute(
                "UPDATE persons SET whitelist = ?1 WHERE id = ?2",
                rusqlite::params![wl as i32, id],
            )
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
        let _ = db::log_command(&guard, "whitelist", &id, true, &cmd.name);
    }
    Ok(Json(serde_json::json!({ "ok": true, "id": id, "name": cmd.name, "host": cmd.host })))
}

fn app(st: AppState) -> Router {
    Router::new()
        .route("/api/health", get(health))
        .route("/api/visits/today", get(visits_today))
        .route("/api/vision/event", post(vision_event))
        .route("/api/door/open", post(door_open))
        .route("/api/door/deny", post(door_deny))
        .route("/api/persons/{id}/tag", post(tag_person))
        .with_state(st)
}

fn seed_demo(conn: &rusqlite::Connection) {
    // İlk açılışta panel boş kalmasın: 1 aile üyesi. Zararsız, tekrar çalışmaz.
    let n: i64 = conn.query_row("SELECT COUNT(*) FROM persons", [], |r| r.get(0)).unwrap_or(1);
    if n == 0 {
        let t = db::now_str();
        let _ = conn.execute(
            "INSERT INTO persons (id, name, tip, whitelist, visit_count, first_seen, last_seen)
             VALUES ('anne', 'Anne', 'aile', 1, 0, ?1, ?1)",
            [t],
        );
    }
}

#[tokio::main]
async fn main() {
    let conn = db::open("iuds.db").expect("sqlite acilamadi");
    seed_demo(&conn);
    let st = AppState { db: Arc::new(tokio::sync::Mutex::new(conn)) };
    let listener = tokio::net::TcpListener::bind("127.0.0.1:3901").await.unwrap();
    println!("iuds-core → http://127.0.0.1:3901/api/health (db: iuds.db)");
    axum::serve(listener, app(st)).await.unwrap();
}

#[cfg(test)]
mod tests {
    use super::*;

    fn test_state() -> AppState {
        let conn = db::open_memory().unwrap();
        AppState { db: Arc::new(tokio::sync::Mutex::new(conn)) }
    }

    #[tokio::test]
    async fn health_ok() {
        let h = health().await;
        assert!(h.0.ok);
    }

    #[tokio::test]
    async fn kapi_bos_token_red() {
        let st = test_state();
        let r = door_open(State(st), Json(DoorCmd { visit_id: "v-1".into(), token: "".into() })).await;
        assert!(r.is_err());
    }

    #[tokio::test]
    async fn vision_anne_oto_ac_yazar() {
        let st = test_state();
        let req = VisionEventReq {
            person_id: Some("anne".into()),
            camera: Some("cam0".into()),
            yuz: 0.93,
            presence: 0.9,
            liveness: 0.85,
            track_suresi: 4.2,
            whitelist: Some(true),
            birlikte_mi: Some(false),
            group_id: None,
        };
        let r = vision_event(State(st.clone()), Json(req)).await.unwrap();
        assert_eq!(r.0.karar, "oto_ac");
        let v = visits_today(State(st)).await.unwrap();
        assert_eq!(v.0.len(), 1);
    }

    #[tokio::test]
    async fn vision_fotograf_red() {
        let st = test_state();
        let req = VisionEventReq {
            person_id: None,
            camera: None,
            yuz: 0.91,
            presence: 0.2,
            liveness: 0.1,
            track_suresi: 4.0,
            whitelist: Some(false),
            birlikte_mi: Some(false),
            group_id: None,
        };
        let r = vision_event(State(st), Json(req)).await.unwrap();
        assert_eq!(r.0.karar, "red");
        assert!(r.0.person_id.starts_with("Ziyaretçi-"));
    }

    #[tokio::test]
    async fn vision_bozuk_skor_400() {
        let st = test_state();
        let req = VisionEventReq {
            person_id: None,
            camera: None,
            yuz: 9.9,
            presence: 0.9,
            liveness: 0.9,
            track_suresi: 4.0,
            whitelist: None,
            birlikte_mi: None,
            group_id: None,
        };
        let r = vision_event(State(st), Json(req)).await;
        assert!(r.is_err());
    }

    #[tokio::test]
    async fn tag_kotu_tip_400() {
        let st = test_state();
        let r = tag_person(
            State(st),
            Path("p1".into()),
            Json(TagCmd { name: "X".into(), host: None, tip: Some("uzayli".into()), whitelist: None }),
        )
        .await;
        assert!(r.is_err());
    }
}

