async fn greet(
    State(st): State<AppState>,
    Json(req): Json<GreetReq>,
) -> Result<Json<GreetResp>, StatusCode> {
    if !["oto_ac", "eslikli_ac", "soruldu", "red"].contains(&req.karar.as_str()) {
        return Err(StatusCode::BAD_REQUEST);
    }
    let text = tts::greet_text(&req.karar, req.name.as_deref());
    let (out, file) = match req.visit_id.clone() {
        Some(vid) if !vid.trim().is_empty() => tts::speak_to_file(&st.tts, &text, vid.trim()).await,
        _ => {
            let o = tts::speak(&st.tts, &text).await;
            (o, None)
        }
    };
    let guard = st.db.lock().await;
    let _ = db::log_command(
        &guard,
        "greet",
        req.visit_id.as_deref().unwrap_or("-"),
        out.spoken,
        &format!("{} bytes={} {}", req.karar, out.bytes, out.detail),
    );
    Ok(Json(GreetResp {
        ok: true,
        text,
        spoken: out.spoken,
        bytes: out.bytes,
        file,
        detail: out.detail,
    }))
}

