+        Some(vid) if !vid.trim().is_empty() => tts::speak_to_file(&st.tts, &text, vid.trim()).await,
+        _ => {
+            let o = tts::speak(&st.tts, &text).await;
+            (o, None)
+        }
+    };
+    let guard = st.db.lock().await;
+    let _ = db::log_command(
+        &guard,
+        "greet",
+        req.visit_id.as_deref().unwrap_or("-"),
+        out.spoken,
+        &format!("{} bytes={} {}", req.karar, out.bytes, out.detail),
+    );
+    Ok(Json(GreetResp {
+        ok: true,
+        text,
+        spoken: out.spoken,
+        bytes: out.bytes,
+        file,
+        detail: out.detail,
+    }))
+}
